-- The keys `BalanceRepository.apply` claims (Plan 20): a room names every write it may have to retry — a
-- cash-out, a buy-in, a buy-in refund, a carry-over release — and `apply` inserts that key first, in the
-- batch's own transaction. A key that is already here makes the call a no-op, so a write that committed but
-- whose acknowledgement was lost is not applied a second time when it is retried.
--
-- Generated by `pnpm --filter @bp/normal-server db:generate --name ledger_keys`, then guarded with
-- IF NOT EXISTS in `0002_outfits.sql`'s style. Purely additive: one new table, no existing row or column
-- touched — `point_transactions` carries no key, and the rows already in it need none.
CREATE TABLE IF NOT EXISTS "ledger_keys" (
	"key" text PRIMARY KEY NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
